const fWorkbook = univerAPI.getActiveWorkbook();
const fWorksheet = fWorkbook.getSheetBySheetId('sheetId');
const fRange = fWorksheet.getRange('A1:A4');

// Auto-fill without specifying applyType (default behavior)
